1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Step of {@code POST /api/owners} that flags a soft duplicate. A new owner that is not a hard
10	 * duplicate (see {@link RequireUniqueIdentity}) but shares an existing owner's last name and
11	 * postcode while having a different telephone is a <em>possible</em> duplicate: it is still created,
12	 * but {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to the matching
13	 * owner's id. Otherwise {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} is
14	 * left unset.
15	 *
16	 * <p>A declared household member (the request set {@code sharesHousehold} to bypass the duplicate
17	 * block) is <em>not</em> a suspected duplicate: it shares an existing owner's last name and postcode
18	 * by declaration, so it is never flagged, whatever its telephone.
19	 *
20	 * <p>Last name is compared case-insensitively; postcode must be present and equal; the telephone is
21	 * compared in its canonical form so an owner with the same telephone (a hard duplicate) is not
22	 * flagged here. When several existing owners match, the one with the lowest id (the earliest) is
23	 * reported. Runs after {@link BuildOwner} so the owner's telephone is already normalized, and before
24	 * {@link SaveOwner} so the owner being created is not compared against itself.
25	 */
26	public class FlagPossibleDuplicate {
27	
28	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            owner.setPossibleDuplicate(false); // a declared household member is not a suspected duplicate
31	            owner.setPossibleDuplicateOf(null);
32	            return;
33	        }
34	        String lastName = owner.getLastName();
35	        String postcode = owner.getPostcode();
36	        String telephone = OwnerIdentity.normalizedTelephone(owner.getTelephone());
37	        Integer matchId = null;
38	        if (postcode != null && !postcode.isBlank()) {
39	            for (Owner existing : ownerRepository.findAll()) {
40	                if (Boolean.TRUE.equals(existing.getDeleted())) {
41	                    continue; // a soft-deleted owner is not a possible-duplicate match
42	                }
43	                if (existing.getId() == null || !lastName.equalsIgnoreCase(existing.getLastName())
44	                        || !postcode.equals(existing.getPostcode())) {
45	                    continue;
46	                }
47	                if (telephone.equals(OwnerIdentity.normalizedTelephone(existing.getTelephone()))) {
48	                    continue; // same telephone: a hard duplicate, not a possible one
49	                }
50	                if (matchId == null || existing.getId() < matchId) {
51	                    matchId = existing.getId();
52	                }
53	            }
54	        }
55	        owner.setPossibleDuplicate(matchId != null);
56	        owner.setPossibleDuplicateOf(matchId);
57	    }
58	}
59

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * SHA-256 hashing to a hexadecimal string — the single place the owner functions compute a digest,
9	 * so everything that derives a value from a hash encodes it the same way. {@link Household#id(String,
10	 * String)} and {@link AssignCustomerCode} both hash through here; a caller that wants a short,
11	 * upper-case code takes a prefix of {@link #hex(String)} and upper-cases it.
12	 */
13	final class Sha256 {
14	
15	    private Sha256() {
16	    }
17	
18	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code input} (64 characters). */
19	    static String hex(String input) {
20	        try {
21	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
22	            StringBuilder sb = new StringBuilder(digest.length * 2);
23	            for (byte b : digest) {
24	                sb.append(String.format("%02x", b));
25	            }
26	            return sb.toString();
27	        }
28	        catch (NoSuchAlgorithmException e) {
29	            throw new IllegalStateException("SHA-256 not available", e);
30	        }
31	    }
32	}
33

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Step of {@code POST /api/owners} that records the owner's {@code householdSize}: the number of
9	 * members its household ({@link Household#id(String, String) same householdId}, i.e. same last name
10	 * and postcode) has once this owner is included. Counts the existing owners sharing the household
11	 * (before this create) and adds one for the owner being created. Runs before {@link SaveOwner} so
12	 * the owner being created is not double-counted. The stored value records the household's size at
13	 * create time.
14	 */
15	public class CountHouseholdMembers {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String householdId = Household.id(owner.getLastName(), owner.getPostcode());
19	        int existing = 0;
20	        for (Owner other : ownerRepository.findAll()) {
21	            if (householdId.equals(Household.id(other.getLastName(), other.getPostcode()))) {
22	                existing++;
23	            }
24	        }
25	        owner.setHouseholdSize(existing + 1);
26	    }
27	}
28

