10	/**
11	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
12	 * canonical region derived from the owner's postcode (falling back to its city; see
13	 * {@link Locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
14	 * {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). The telephone is normalized to
15	 * E.164 form (see {@link OwnerIdentity#normalizedTelephone(String)}), the same normalization used by
16	 * the identity key. The code carries no per-city sequence, so it is derived purely from the owner's
17	 * own fields and is seed-independent.
18	 *
19	 * <p>When the computed code collides with an existing owner's {@code customerCode}, {@code -<n>} is
20	 * appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners always
21	 * receive distinct customer codes.
22	 */
23	public class AssignCustomerCode {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
26	        String region = Locality.of(owner.getPostcode(), owner.getCity());
27	        String hash8 = hash8(OwnerIdentity.normalizedTelephone(owner.getTelephone()), owner.getLastName());
28	        String base = region + "-" + hash8;
29	        owner.setCustomerCode(deduplicate(base, ownerRepository));
30	    }
31	
32	    /**
33	     * The base code if no existing owner already uses it, otherwise {@code base-<n>} with the
34	     * smallest {@code n} of 2 or more that is not already taken.
35	     */
36	    private static String deduplicate(String base, OwnerRepository ownerRepository) {
37	        Set<String> existing = new HashSet<>();
38	        for (Owner other : ownerRepository.findAll()) {
39	            String code = other.getCustomerCode();
40	            if (code != null) {
41	                existing.add(code);
42	            }
43	        }
44	        if (!existing.contains(base)) {
45	            return base;
46	        }
47	        for (int n = 2; ; n++) {
48	            String candidate = base + "-" + n;
49	            if (!existing.contains(candidate)) {
50	                return candidate;
51	            }
52	        }
53	    }
54	
55	    /** First 8 upper-case hex characters of SHA-256 over {@code (normalizedTelephone + lastName)}. */
56	    private static String hash8(String normalizedTelephone, String lastName) {
57	        String input = normalizedTelephone + (lastName == null ? "" : lastName);
58	        return Sha256.hex(input).substring(0, 8).toUpperCase();
59	    }
60	}
