13	/**
14	 * First step of {@code POST /api/owners}. Rejects a request that is missing or blank in any
15	 * required owner field before {@link BuildOwner} runs, throwing {@link MissingFieldsException}
16	 * (handled as a 400 listing the offending field names). Normalizes the address (see
17	 * {@link OwnerAddress}) before that check, so an address left blank once whitespace is collapsed is
18	 * rejected as missing. Normalizes the telephone to E.164 form (see {@link OwnerTelephone}), throwing
19	 * {@link InvalidTelephoneException} (400) when it cannot form a valid number. Publishes the
20	 * normalized body for later steps, so the stored, returned and compared address is the normalized
21	 * form.
22	 */
23	public class RequireOwnerFields {
24	
25	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
26	            throws MissingFieldsException, InvalidTelephoneException, InvalidEmailException {
27	        // Prefer the structured address when supplied, falling back to the flat 'address' for
28	        // backward compatibility. Store each supplied part in its normalized form and expose the
29	        // composed 'address' (normalized addressLine1, plus normalized addressLine2 after a single
30	        // space when present) so the required-field check, storage and every reader see one form.
31	        request.setAddressLine1(OwnerAddress.normalizeOrNull(request.getAddressLine1()));
32	        request.setAddressLine2(OwnerAddress.normalizeOrNull(request.getAddressLine2()));
33	        request.setAddress(OwnerAddress.compose(request.getAddressLine1(), request.getAddressLine2(),
34	                request.getAddress()));
35	        List<String> missing = new ArrayList<>();
36	        if (isBlank(request.getFirstName())) {
37	            missing.add("firstName");
38	        }
39	        if (isBlank(request.getLastName())) {
40	            missing.add("lastName");
41	        }
42	        if (isBlank(request.getAddress())) {
43	            missing.add("address");
44	        }
45	        if (isBlank(request.getCity())) {
46	            missing.add("city");
47	        }
48	        if (isBlank(request.getTelephone())) {
49	            missing.add("telephone");
50	        }
51	        if (!missing.isEmpty()) {
52	            throw new MissingFieldsException(missing);
